from collections import Counter
def transform(grid):
    H, W = len(grid), len(grid[0])
    colors = Counter(x for r in grid for x in r)
    sep = None
    for c in colors:
        if any(all(grid[i][j]==c for j in range(W)) for i in range(H)) and any(all(grid[i][j]==c for i in range(H)) for j in range(W)):
            sep = c; break
    rsep=[i for i in range(H) if all(grid[i][j]==sep for j in range(W))]
    csep=[j for j in range(W) if all(grid[i][j]==sep for i in range(H))]
    rs=[-1]+rsep+[H]; cs=[-1]+csep+[W]
    inner=Counter()
    for i in range(len(rs)-1):
        for j in range(len(cs)-1):
            for r in grid[rs[i]+1:rs[i+1]]:
                for x in r[cs[j]+1:cs[j+1]]:
                    inner[x]+=1
    bg=inner.most_common(1)[0][0]
    mk=[c for c in inner if c!=bg][0]
    out=[]
    for i in range(len(rs)-1):
        row=[]
        for j in range(len(cs)-1):
            n=sum(1 for x in range(rs[i]+1,rs[i+1]) for y in range(cs[j]+1,cs[j+1]) if grid[x][y]==mk)
            row.append(1 if n%2==0 else bg)
        out.append(row)
    return out
